#include <stdio.h>
void tg14_init(void); int tg14_enqueue(unsigned, unsigned*, unsigned*); int tg14_accept(unsigned, unsigned, unsigned*); void tg14_force_reuse(unsigned, unsigned); unsigned tg14_state_digest(void);
int main(void){unsigned s0=0,g0=0,s1=0,g1=0,s2=0,g2=0,s3=0,g3=0,w0=0,wg0=0,v=0,a=0,d=0,h=0;tg14_init();(void)tg14_enqueue(33u,&s0,&g0);(void)tg14_enqueue(66u,&s1,&g1);tg14_force_reuse(s0,77u);(void)tg14_enqueue(99u,&s2,&g2);tg14_force_reuse(s1,111u);(void)tg14_enqueue(132u,&s3,&g3);(void)tg14_enqueue(165u,&w0,&wg0);tg14_force_reuse(s2,143u); if(tg14_accept(s0,g0,&v)){a++;h=(h*131u)^v;}else d++; if(tg14_accept(s0,g0+1u,&v)){a++;h=(h*131u)^v;}else d++; if(tg14_accept(s1,g1,&v)){a++;h=(h*131u)^v;}else d++; if(tg14_accept(s1,g1+1u,&v)){a++;h=(h*131u)^v;}else d++; if(tg14_accept(s2,g2,&v)){a++;h=(h*131u)^v;}else d++; if(tg14_accept(s3,g3,&v)){a++;h=(h*131u)^v;}else d++; if(tg14_accept(w0,wg0,&v)){a++;h=(h*131u)^v;}else d++; printf("%u %u %u %u\n",a,d,h,tg14_state_digest()); return 0; }
